#include <stdio.h>
#include <stdlib.h>

#define MAXN 305
#define MAXT 22505

static short dp[2][MAXN][MAXT];
static int P[MAXN];
static int A[MAXN];

int main() {
    int N, K;
    long long T_in;
    if (scanf("%d %d %lld", &N, &K, &T_in) != 3) {
        return 0;
    }

    for (int i = 1; i <= N; i++) {
        scanf("%d", &P[i]);
    }

    int k_count = 0;
    for (int i = 1; i <= N; i++) {
        int g;
        scanf("%d", &g);
        if (g == 1) {
            k_count++;
            A[k_count] = i;
        }
    }

    long long max_possible_T = (long long)K * (N - K);
    if (T_in > max_possible_T) {
        T_in = max_possible_T;
    }
    int T = (int)T_in;

    // Inicialização da base: com 0 amigos, ganho é 0 para qualquer j e t >= 0
    for (int j = 0; j <= N; j++) {
        for (int t = 0; t <= T; t++) {
            dp[0][j][t] = 0;
        }
    }

    for (int i = 1; i <= K; i++) {
        int cur_i = i & 1;
        int prev_i = (i - 1) & 1;

        // Com i amigos, não é possível terminar em posições < i
        for (int t = 0; t <= T; t++) {
            dp[cur_i][i - 1][t] = -1;
        }

        int max_j = N - K + i;
        for (int j = i; j <= max_j; j++) {
            int cost = abs(A[i] - j);
            int p = P[j];

            short *prev = dp[prev_i][j - 1];
            short *cur = dp[cur_i][j];
            short *cur_prev_j = dp[cur_i][j - 1];

            int limit = cost < T ? cost : T + 1;
            for (int t = 0; t < limit; t++) {
                cur[t] = cur_prev_j[t];
            }

            for (int t = cost; t <= T; t++) {
                short val = prev[t - cost];
                short v = (val >= 0) ? (short)(val + p) : (short)-1;
                short keep = cur_prev_j[t];
                cur[t] = (v > keep) ? v : keep;
            }
        }
    }

    short ans = dp[K & 1][N][T];
    if (ans < 0) ans = 0;

    printf("%d\n", ans);

    return 0;
}
