#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INF 1000000000

static int dp[305][2705];
static int next_dp[305][2705];
static int P[305];
static int G[305];
static int orig[305];

static inline int min(int a, int b) {
    return a < b ? a : b;
}

static inline int abs_val(int a) {
    return a < 0 ? -a : a;
}

int main() {
    int N, K;
    long long T;
    if (scanf("%d %d %lld", &N, &K, &T) != 3) return 0;

    for (int i = 1; i <= N; i++) {
        scanf("%d", &P[i]);
    }

    orig[0] = 0;
    for (int i = 1; i <= N; i++) {
        scanf("%d", &G[i]);
        orig[i] = orig[i - 1] + G[i];
    }

    int max_V = 9 * K;

    for (int j = 0; j <= K; j++) {
        for (int v = 0; v <= max_V; v++) {
            dp[j][v] = INF;
        }
    }
    dp[0][0] = 0;

    for (int i = 1; i <= N; i++) {
        int max_j = min(i, K);
        int p = P[i];

        for (int j = 0; j <= max_j; j++) {
            int current_max_v = 9 * j;
            int cut_cost = abs_val(j - orig[i]);

            for (int v = 0; v <= current_max_v; v++) {
                int res = dp[j][v]; // Não colocar amigo na posição i

                if (j > 0 && v >= p) {
                    int with_friend = dp[j - 1][v - p];
                    if (with_friend < res) {
                        res = with_friend;
                    }
                }

                if (res < INF) {
                    next_dp[j][v] = res + cut_cost;
                } else {
                    next_dp[j][v] = INF;
                }
            }
            // Para valores acima de current_max_v até max_V
            for (int v = current_max_v + 1; v <= max_V; v++) {
                next_dp[j][v] = INF;
            }
        }
        for (int j = max_j + 1; j <= K; j++) {
            for (int v = 0; v <= max_V; v++) {
                next_dp[j][v] = INF;
            }
        }

        // Copia next_dp para dp
        for (int j = 0; j <= max_j; j++) {
            int current_max_v = 9 * j;
            for (int v = 0; v <= current_max_v; v++) {
                dp[j][v] = next_dp[j][v];
            }
            for (int v = current_max_v + 1; v <= max_V; v++) {
                dp[j][v] = INF;
            }
        }
    }

    int ans = 0;
    for (int v = 0; v <= max_V; v++) {
        if (dp[K][v] <= T) {
            if (v > ans) {
                ans = v;
            }
        }
    }

    printf("%d\n", ans);

    return 0;
}
